                { day: 15, debit: 'accountsReceivable', credit: 'salesRevenue', amount: 2000,
                  en: 'Sells clothing to a corporate client on credit (due in 15 days): $2,000.',
                  es: 'Vende ropa a un cliente corporativo a crédito (plazo 15 días): $2,000.' },
                { day: 15, debit: 'cogs', credit: 'inventory', amount: 1000,
                  en: 'Records the cost of goods sold for the credit sale. The inventory cost was $1,000.',
                  es: 'Registra el costo de ventas de la venta a crédito. El costo del inventario fue $1,000.' },
                { day: 18, debit: 'cash', credit: 'bankLoan', amount: 10000,
                  en: 'Receives a bank loan for working capital: $10,000.',
                  es: 'Recibe un préstamo bancario para capital de trabajo: $10,000.' },
                { day: 20, debit: 'inventory', credit: 'cash', amount: 6000,
                  en: 'Uses part of the loan to purchase additional inventory: $6,000.',
                  es: 'Usa parte del préstamo para comprar inventario adicional: $6,000.' },
                { day: 22, debit: 'cash', credit: 'salesRevenue', amount: 4500,
                  en: 'Sells more inventory for cash: $4,500.',
                  es: 'Vende más inventario en efectivo: $4,500.' },
                { day: 22, debit: 'cogs', credit: 'inventory', amount: 2250,
                  en: 'Records the cost of goods sold for this sale. The inventory cost was $2,250.',
                  es: 'Registra el costo de ventas de esta venta. El costo del inventario fue $2,250.' },
                { day: 25, debit: 'utilitiesExpense', credit: 'cash', amount: 300,
                  en: 'Pays utilities for the first three weeks: $300.',
                  es: 'Paga servicios públicos de las primeras tres semanas: $300.' },
                { day: 27, debit: 'cash', credit: 'accountsReceivable', amount: 1000,
                  en: 'Receives partial payment from the corporate customer on the credit sale: $1,000.',
                  es: 'Recibe pago parcial del cliente corporativo por la venta a crédito: $1,000.' },
                { day: 28, debit: 'salariesExpense', credit: 'cash', amount: 1200,
                  en: 'Pays the second two-week salary for employees: $1,200.',
                  es: 'Paga el segundo salario quincenal de los empleados: $1,200.' },
                { day: 30, debit: 'deprExpense', credit: 'accumDepr', amount: 20.83,
                  en: 'Records monthly depreciation on store equipment. Cost $5,000 / 20 years / 12 months = $20.83.',
                  es: 'Registra la depreciación mensual del equipo. Costo $5,000 / 20 años / 12 meses = $20.83.' }
            ];

            // 1.2.0: the analysis panels show the ledger the student posted (computed from EVENTS),
            // not pre-classified lists with the subtotals already worked out (EQIL W2, L2).
            this.ANALYSIS = [
                { phase: 2, kind: 'tb', tolerance: 0.02,
                  heading_en: 'Phase 2: Verify Trial Balance',
                  heading_es: 'Fase 2: Verificar la balanza de comprobación',
                  label_en: 'Enter total debits ($):',
                  label_es: 'Ingrese el total de débitos ($):',
                  info_en: 'These are the ledger balances after your 18 entries, in chart-of-accounts order, without the side. Decide which accounts carry a debit balance and add them: in a balanced trial balance that total equals the credit total.',
                  info_es: 'Estos son los saldos del libro mayor después de sus 18 asientos, en el orden del catálogo de cuentas y sin indicar el lado. Decida qué cuentas tienen saldo deudor y súmelas: en una balanza cuadrada ese total es igual al total acreedor.' },
                { phase: 3, kind: 'ni', tolerance: 0.02,
                  heading_en: 'Phase 3: Income Statement',
                  heading_es: 'Fase 3: Estado de resultados',
                  label_en: 'Enter Net Income ($):',
                  label_es: 'Ingrese la utilidad neta ($):',
                  info_en: 'Net income = net sales (sales minus returns) minus cost of goods sold minus operating expenses. Take each figure from the ledger below.',
                  info_es: 'Utilidad neta = ventas netas (ventas menos devoluciones) menos costo de ventas menos gastos operativos. Tome cada cifra del libro mayor de abajo.' },
                { phase: 3, kind: 'ta', tolerance: 0.02,
                  heading_en: 'Phase 3: Balance Sheet',
                  heading_es: 'Fase 3: Balance general',
                  label_en: 'Enter Total Assets ($):',
                  label_es: 'Ingrese el total de activos ($):',
                  info_en: 'Total assets = every asset account in the ledger below; an account that reduces an asset is subtracted from it.',
                  info_es: 'Total de activos = todas las cuentas de activo del libro mayor de abajo; una cuenta que reduce un activo se resta de él.' },
                { phase: 4, kind: 'cr', tolerance: 0.05,
                  heading_en: 'Phase 4: Financial Ratio Analysis',
                  heading_es: 'Fase 4: Análisis de razones financieras',
                  label_en: 'Enter the Current Ratio (2 decimals):',
                  label_es: 'Ingrese la razón corriente (2 decimales):',
                  info_en: 'Current ratio = current assets / current liabilities, rounded to 2 decimals. The working-capital bank loan is repayable within twelve months.',
                  info_es: 'Razón corriente = activos corrientes / pasivos corrientes, redondeada a 2 decimales. El préstamo bancario de capital de trabajo se paga dentro de los próximos doce meses.' }
            ];
            this.TYPES = { cash: 'asset', accountsReceivable: 'asset', inventory: 'asset', storeEquipment: 'asset', accumDepr: 'contraAsset',
                accountsPayable: 'liability', bankLoan: 'liability', salariesPayable: 'liability', commonStock: 'equity', retainedEarnings: 'equity',
                salesRevenue: 'revenue', salesReturns: 'contraRevenue', cogs: 'expense', salariesExpense: 'expense', rentExpense: 'expense',
                utilitiesExpense: 'expense', deprExpense: 'expense', interestExpense: 'expense' };
            // 1.3.0: the grade is built on six concepts (TN 080 LO1 to LO4, section 7 Q1 and Q2, section 5.2;
            // the case, Industry and Market Context, on inventory). A concept is kept only when every item that
            // tests it was right on the first try. On the routine entries only an account error (or an entry
            // that does not balance) loses the concept: an amount typo there costs accuracy points only.
            // Grade = 10 per concept kept (60) + 40 x item points / 66 (3, 2, 1 or 0 points per item as before).
            this.CONCEPTS = [
                { key: 'inv', items: [4, 6, 10, 12, 14] },
                { key: 'ret', items: [7, 20] },
                { key: 'dep', items: [18, 21] },
                { key: 'coll', items: [16] },
                { key: 'cls', items: [19, 22] },
                { key: 'rule', items: [1, 2, 3, 5, 8, 9, 11, 13, 15, 17], accountsOnly: true }
            ];
            var L = this._ledgerFigures();
            this.ANALYSIS[0].answer = L.tb;
            this.ANALYSIS[1].answer = L.ni;
            this.ANALYSIS[2].answer = L.ta;
            this.ANALYSIS[3].answer = L.cr;
        }

        _r2(x) { return Math.round(x * 100) / 100; }

        // Net debit balance per account (positive = debit balance), from the 18 events.
        _ledger() {
            var b = {}, i;
            for (i = 0; i < this.ACCOUNTS.length; i++) b[this.ACCOUNTS[i].key] = 0;
            for (i = 0; i < this.EVENTS.length; i++) {
                var e = this.EVENTS[i];
                b[e.debit] += e.amount;
                b[e.credit] -= e.amount;
            }
            for (var k in b) b[k] = this._r2(b[k]);
            return b;
        }

        _ledgerFigures() {
            var b = this._ledger(), T = this.TYPES, tb = 0, ta = 0, ni = 0, k;
            for (k in b) {
                if (b[k] > 0) tb += b[k];
                if (T[k] === 'asset' || T[k] === 'contraAsset') ta += b[k];
                if (T[k] === 'revenue' || T[k] === 'contraRevenue' || T[k] === 'expense') ni -= b[k];
            }
            var ca = b.cash + b.accountsReceivable + b.inventory;
            var cl = -(b.accountsPayable + b.bankLoan + b.salariesPayable);
            var netSales = -(b.salesRevenue + b.salesReturns);
            var equityClosed = -(b.commonStock + b.retainedEarnings) + ni;
            return { tb: this._r2(tb), ta: this._r2(ta), ni: this._r2(ni), cr: this._r2(ca / cl),
                ca: ca, ap: -b.accountsPayable, contraAsset: -b.accumDepr, returns: b.salesReturns,
                netSales: netSales, gross: netSales - b.cogs, liab: cl, equityClosed: equityClosed };
        }

        _money(x) {
            var neg = x < 0, v = Math.abs(x), s = v.toFixed(2), parts = s.split('.');
            parts[0] = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');
            return (neg ? '-' : '') + '$' + (parts[1] === '00' ? parts[0] : parts.join('.'));
        }

        _ledgerTable(lang) {
            var b = this._ledger(), rows = '';
            for (var i = 0; i < this.ACCOUNTS.length; i++) {
                var a = this.ACCOUNTS[i];
                if (!b[a.key]) continue;
                rows += '<tr><td>' + a.code + '</td><td>' + (lang === 'es' ? a.es : a.en) + '</td><td class="acctgame-num">' + this._money(Math.abs(b[a.key])) + '</td></tr>';
            }
            var cap = lang === 'es' ? 'Saldos del libro mayor después del evento 18' : 'Ledger balances after event 18';
            var h = lang === 'es' ? ['Código', 'Cuenta', 'Saldo'] : ['Code', 'Account', 'Balance'];
            return '<table class="acctgame-ledger"><caption>' + cap + '</caption><thead><tr><th scope="col">' + h[0] + '</th><th scope="col">' + h[1] +
                '</th><th scope="col" class="acctgame-num">' + h[2] + '</th></tr></thead><tbody>' + rows + '</tbody></table>';
        }

        _fill(str, o) { return String(str).replace(/\{(\w+)\}/g, function (m, k) { return o[k] !== undefined ? o[k] : m; }); }

        // Which misconception a refused attempt shows (TN 080 sections 5.2, 7 Q1, 12 prompt a).
        _classifySlip(sl) {
            var T = this.TYPES;
            if (sl.p <= 18) {
                var e = this.EVENTS[sl.p - 1];
                if (sl.p === 7 && sl.d === 'salesRevenue') return 'contraRevenue';
                if (sl.p === 18 && sl.c === 'storeEquipment') return 'contraAsset';
                if ((sl.p === 4 || sl.p === 12) && T[sl.d] === 'expense') return 'inventoryExpensed';
                if (sl.d === e.credit && sl.c === e.debit) return 'reversed';
                if ((sl.d !== e.debit && T[sl.d] === T[e.debit]) || (sl.c !== e.credit && T[sl.c] === T[e.credit])) return 'sameNormal';
                if (sl.p === 16 && sl.d === e.debit && sl.c === e.credit && Math.abs(sl.a - 2000) < 0.01) return 'fullCollection';
                if (sl.d === e.debit && sl.c === e.credit) return 'amount';
                return 'side';
            }
            var L = this._ledgerFigures(), x = sl.x;
            if (sl.p === 19 && Math.abs(x - (L.tb + L.contraAsset)) < 0.02) return 'tbSides';
            if (sl.p === 20 && Math.abs(x - (L.ni + L.returns)) < 0.02) return 'grossRevenue';
            if (sl.p === 21 && Math.abs(x - (L.ta + L.contraAsset)) < 0.02) return 'grossAssets';
            if (sl.p === 22 && Math.abs(x - this._r2(L.ca / L.ap)) < 0.05) return 'loanCurrent';
            return 'calc';
        }

        _slipText(t, tok) {
            var parts = String(tok).split(':'), lang = this._getLang();
            var o = { n: parts[0], used: '', right: '' };
            if (parts[2]) { var ab = parts[2].split('>'); o.used = this._acctName(ab[0], lang); o.right = this._acctName(ab[1], lang); }
            var txt = t('mis_' + parts[1]);
            return txt === 'mis_' + parts[1] ? '' : this._fill(txt, o);
        }

        // Resolve the active language, preferring the framework i18n module so that the
        // dynamic content (events, analysis, briefing) always matches the static UI and
        // follows runtime language switches. Falls back to <html lang>, then 'en'.
        _getLang() {
            try {
                if (window.vcI18n && window.vcI18n._lang) {
                    return String(window.vcI18n._lang).toLowerCase().indexOf('es') === 0 ? 'es' : 'en';
                }
            } catch (e) {}
            var html = document.documentElement;
            if (html && html.lang && html.lang.toLowerCase().indexOf('es') === 0) return 'es';
            return 'en';
        }

        _t() {
            return (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function(k) { return k; };
        }

        _populateDropdowns() {
            var lang = this._getLang();
            var debitSel = document.getElementById('debitAccount');
            var creditSel = document.getElementById('creditAccount');
            if (!debitSel || !creditSel) return;

            var placeholder = lang === 'es' ? '-- Seleccione una cuenta --' : '-- Select an account --';
            var html = '<option value="">' + placeholder + '</option>';
            for (var i = 0; i < this.ACCOUNTS.length; i++) {
                var a = this.ACCOUNTS[i];
                var name = lang === 'es' ? a.es : a.en;
                html += '<option value="' + a.key + '">' + a.code + ' - ' + name + '</option>';
            }
            debitSel.innerHTML = html;
            creditSel.innerHTML = html;
        }

        _updateBriefing(state) {
            var period = (state && state.currentPeriod) || 1;
            var lang = this._getLang();
            var phaseEl = document.getElementById('phaseTitle');
            var briefEl = document.getElementById('briefingText');
            var journalPanel = document.getElementById('journalPanel');
            var analysisPanel = document.getElementById('analysisPanel');

            if (period <= 18) {
                var idx = Math.min(period - 1, this.EVENTS.length - 1);
                var evt = this.EVENTS[idx];
                if (phaseEl) {
                    phaseEl.textContent = lang === 'es'
                        ? 'Fase 1: Asientos contables — Evento ' + period + ' de 18'
                        : 'Phase 1: Journal Entries — Event ' + period + ' of 18';
                }
                if (briefEl) {
                    var dayLabel = lang === 'es' ? 'Mes 1, Día ' : 'Month 1, Day ';
                    briefEl.innerHTML = '<strong>' + dayLabel + evt.day + '</strong><br>' + (lang === 'es' ? evt.es : evt.en);
                }
                if (journalPanel) journalPanel.style.display = 'block';
                if (analysisPanel) analysisPanel.style.display = 'none';
                this._populateDropdowns();
            } else {
                var aIdx = Math.min(period - 19, this.ANALYSIS.length - 1);
                var task = this.ANALYSIS[aIdx];
                if (phaseEl) phaseEl.textContent = lang === 'es' ? task.heading_es : task.heading_en;
                if (briefEl) briefEl.innerHTML = '';
                if (journalPanel) journalPanel.style.display = 'none';
                if (analysisPanel) analysisPanel.style.display = 'block';

                var heading = document.getElementById('analysisHeading');
                if (heading) heading.textContent = lang === 'es' ? task.heading_es : task.heading_en;
                var info = document.getElementById('analysisInfo');
                if (info) info.innerHTML = '<p>' + (lang === 'es' ? task.info_es : task.info_en) + '</p>' + this._ledgerTable(lang);
                var label = document.getElementById('analysisLabel');
                if (label) label.textContent = lang === 'es' ? task.label_es : task.label_en;
                var input = document.getElementById('analysisInput');
                if (input && this._briefPeriod !== period) input.value = '';
            }
            this._briefPeriod = period;

            var feedback = document.getElementById('feedbackArea');
            if (feedback) feedback.innerHTML = '';
        }

        initialize(state) {
            // Reset on a fresh start OR when history is empty (undo back to the beginning).
            // The framework calls initialize() again after undoLastPeriod() pops the last
            // history entry; keying the reset on history (not on a non-empty domainState)
            // ensures a replay starts from zero instead of double-counting the score.
            // Resume mid-game (history present) keeps the loaded domainState untouched.
            var ds = state.domainState;
            var needsReset = !ds || Object.keys(ds).length === 0 || !state.history || state.history.length === 0;
            if (needsReset) {
                state.domainState = {
                    score: 0,
                    totalCorrect: 0,
                    firstTry: 0,
                    totalAttempts: 0,
                    currentAttempts: 0,
                    scoreHistory: [],
                    items: [],
                    slips: [],
                    gradeShown: '',
                    performance: { overallScore: 0, grade: 'F', tier: 'tier_beginner', insights: [] }
                };
            } else if (!state.domainState.performance) {
                // Resumed from a pre-1.1.0 save that predates the grade block — make sure
                // the key the grading layer reads always exists.
                state.domainState.performance = { overallScore: 0, grade: 'F', tier: 'tier_beginner', insights: [] };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    debitAccount: '',
                    creditAccount: '',
                    debitAmount: 0,
                    creditAmount: 0,
                    analysisAnswer: 0
                };
            }
            this._updateBriefing(state);
        }

        // The attempt log lives on the state object, outside domainState: an undo restores domainState from
        // history, so attempts kept there could be erased by undoing the task before. A reset builds a new
        // state object and starts a new log. A reload starts from what was saved (completed tasks are in
        // domainState.items; the open task from domainState.currentAttempts).
        _log(state) {
            if (!state._acctLog) state._acctLog = { tries: {}, done: {}, miss: {}, slips: {} };
            return state._acctLog;
        }

        _conceptOf(p) {
            for (var i = 0; i < this.CONCEPTS.length; i++) {
                if (this.CONCEPTS[i].items.indexOf(p) >= 0) return this.CONCEPTS[i];
            }
            return null;
        }

        // Counts a genuine attempt once. A task already accepted (replayed after an undo) is not counted again.
        _countAttempt(state, period, missKind) {
            var ds = state.domainState, log = this._log(state);
            if (log.done[period]) return;
            var n = Math.max(log.tries[period] || 0, ds.currentAttempts || 0) + 1;
            log.tries[period] = n;
            ds.currentAttempts = n;
            if (n === 1 && missKind) { log.miss[period] = missKind; ds.firstMiss = missKind; }
            var items = Array.isArray(ds.items) ? ds.items : [], tot = 0;
            for (var i = 0; i < items.length && i < period - 1; i++) { if (items[i]) tot += items[i].a || 0; }
            ds.totalAttempts = tot + n;
            var attemptsEl = document.getElementById('attemptsDisplay');
            if (attemptsEl) attemptsEl.textContent = ds.totalAttempts;
        }

        _wrong(html) { return '<span class="acctgame-wrong">' + html + '</span>'; }

        validateDecisions(decisions) {
            var state = window.mySimulation.state;
            var period = state.currentPeriod || 1;
            var lang = this._getLang();
            var t = this._t();
            var feedback = document.getElementById('feedbackArea');
            var log = this._log(state);

            if (period <= 18) {
                var debitSel = document.getElementById('debitAccount');
                var creditSel = document.getElementById('creditAccount');
                var debitAmt = document.getElementById('debitAmount');
                var creditAmt = document.getElementById('creditAmount');

                decisions.debitAccount = debitSel ? debitSel.value : '';
                decisions.creditAccount = creditSel ? creditSel.value : '';
                decisions.debitAmount = debitAmt ? parseFloat(debitAmt.value) || 0 : 0;
                decisions.creditAmount = creditAmt ? parseFloat(creditAmt.value) || 0 : 0;

                // Presence checks first: an incomplete form is not a scored attempt.
                if (!decisions.debitAccount || !decisions.creditAccount) {
                    window.mySimulation.uiManager.showNotification(t('select_accounts_warning'), 'warning');
                    return false;
                }
                if (decisions.debitAmount <= 0 || decisions.creditAmount <= 0) {
                    window.mySimulation.uiManager.showNotification(t('enter_amounts_warning'), 'warning');
                    return false;
                }

                var evt = this.EVENTS[period - 1];

                if (Math.abs(decisions.debitAmount - decisions.creditAmount) > 0.01) {
                    this._countAttempt(state, period, 'acct');
                    if (feedback) feedback.innerHTML = this._wrong(this._fill(t('fb_unbalanced'), { d: this._money(decisions.debitAmount), c: this._money(decisions.creditAmount) }));
                    return false;
                }

                var acctWrong = decisions.debitAccount !== evt.debit || decisions.creditAccount !== evt.credit;
                var amtWrong = Math.abs(decisions.debitAmount - evt.amount) > 0.01;
                if (acctWrong || amtWrong) {
                    this._countAttempt(state, period, acctWrong ? 'acct' : 'amount');
                    var sl = { p: period, d: decisions.debitAccount, c: decisions.creditAccount, a: decisions.debitAmount };
                    var kind = this._recordSlip(state, sl);
                    var errors = [];
                    if (decisions.debitAccount !== evt.debit) errors.push(t('fb_debit'));
                    if (decisions.creditAccount !== evt.credit) errors.push(t('fb_credit'));
                    if (amtWrong) errors.push(t('fb_amount'));
                    // the close calls the teaching note names are explained at once (EQIL L9)
                    var why = (kind === 'contraRevenue' || kind === 'contraAsset' || kind === 'inventoryExpensed' || kind === 'sameNormal' || kind === 'fullCollection')
                        ? this._slipText(t, sl.p + ':' + kind + (kind === 'sameNormal' ? ':' + this._sameNormalPair(sl) : '')) : '';
                    if (why) errors.push(why);
                    if ((log.tries[period] || state.domainState.currentAttempts) >= 3) {
                        errors.push('<em>' + this._fill(t('fb_hint_entry'), { d: this._acctName(evt.debit, lang), c: this._acctName(evt.credit, lang), a: this._money(evt.amount) }) + '</em>');
                    }
                    if (feedback) feedback.innerHTML = this._wrong(errors.join('<br>'));
                    return false;
                }

                this._countAttempt(state, period, '');
                if (feedback) feedback.innerHTML = '<span class="acctgame-correct">' + t('fb_correct') + '</span>';
                return true;

            } else {
                var input = document.getElementById('analysisInput');
                decisions.analysisAnswer = input ? parseFloat(input.value) || 0 : 0;

                if (decisions.analysisAnswer <= 0) {
                    window.mySimulation.uiManager.showNotification(t('enter_answer_warning'), 'warning');
                    return false;
                }

                var task = this.ANALYSIS[period - 19];
                if (Math.abs(decisions.analysisAnswer - task.answer) > task.tolerance) {
                    this._countAttempt(state, period, 'value');
                    var k2 = this._recordSlip(state, { p: period, x: decisions.analysisAnswer });
                    var msg = t('fb_value');
                    var why2 = k2 && k2 !== 'calc' ? this._slipText(t, period + ':' + k2) : '';
                    if (why2) msg += '<br>' + why2;
                    if ((log.tries[period] || state.domainState.currentAttempts) >= 3) {
                        msg += '<br><em>' + this._fill(t('fb_hint_value'), { x: task.kind === 'cr' ? task.answer.toFixed(2) : this._money(task.answer) }) + '</em>';
                    }
                    if (feedback) feedback.innerHTML = this._wrong(msg);
                    return false;
                }

                this._countAttempt(state, period, '');
                if (feedback) feedback.innerHTML = '<span class="acctgame-correct">' + t('fb_correct') + '</span>';
                return true;
            }
        }

        _sameNormalPair(sl) {
            var e = this.EVENTS[sl.p - 1];
            return sl.d !== e.debit && this.TYPES[sl.d] === this.TYPES[e.debit] ? sl.d + '>' + e.debit : sl.c + '>' + e.credit;
        }

        // Each refused attempt is classified at once and kept as one short token per period and
        // kind (period:kind[:account]), so the saved state stays small however many attempts a run takes.
        // Tokens go to the attempt log as well, so an undo of the task before does not erase them.
        _recordSlip(state, sl) {
            var ds = state.domainState, log = this._log(state);
            if (!Array.isArray(ds.slips)) ds.slips = [];
            var kind = this._classifySlip(sl);
            if (kind === 'calc') return kind;
            var tok = sl.p + ':' + kind;
            if (kind === 'sameNormal') tok += ':' + this._sameNormalPair(sl);
            if (!log.slips[sl.p]) log.slips[sl.p] = [];
            if (log.slips[sl.p].indexOf(tok) < 0) log.slips[sl.p].push(tok);
            if (ds.slips.indexOf(tok) < 0 && ds.slips.length < 60) ds.slips.push(tok);
            return kind;
        }

        _acctName(key, lang) {
            for (var i = 0; i < this.ACCOUNTS.length; i++) {
                if (this.ACCOUNTS[i].key === key) return lang === 'es' ? this.ACCOUNTS[i].es : this.ACCOUNTS[i].en;
            }
            return key;
        }

        // One function derives the grade, the band, the letter and the concepts from the items played,
        // re-summed every time (undo-safe, EQIL G-D). Accuracy is taken over the items played so far,
        // so the grade shown during the game is the grade so far; after task 22 it is the final grade.
        _grade(items) {
            var pts = 0, first = 0, n = 0, att = 0, hints = 0, lost = {}, tested = {}, firstJ = 0;
            for (var i = 0; i < items.length; i++) {
                var it = items[i];
                if (!it) continue;
                var a = it.a || 1, p = i + 1, cp = this._conceptOf(p);
                n++; att += a;
                if (cp) tested[cp.key] = true;
                pts += a === 1 ? 3 : (a === 2 ? 2 : (a === 3 ? 1 : 0));
                if (a >= 4) hints++;
                if (a === 1) { first++; if (p <= 18) firstJ++; continue; }
                var c = this._conceptOf(p);
                if (c && !(c.accountsOnly && it.m === 'amount')) lost[c.key] = true;
            }
            var kept = 0, held = {}, nt = 0, kt = 0;
            for (var k = 0; k < this.CONCEPTS.length; k++) {
                var key = this.CONCEPTS[k].key;
                held[key] = !lost[key];
                if (!lost[key]) kept++;
                if (tested[key]) { nt++; if (!lost[key]) kt++; }
            }
            var acc = n ? pts / (3 * n) : 1;
            var accPts = Math.round(40 * acc * 10) / 10;
            // during the game only the concepts already tested count (the share kept so far); after task 22 all six are
            var share = nt ? kt / nt : 1;
            var overall = Math.max(0, Math.min(100, Math.round(40 * acc + 60 * share)));
            return { points: pts, first: first, firstJ: firstJ, firstA: first - firstJ, n: n, attempts: att, hints: hints,
                kept: kept, held: held, accuracy: accPts, concepts: 10 * kept, overall: overall };
        }

        _band(score) {
            if (score >= 90) return { grade: 'A', tier: 'tier_excellent', insight: 'insight_excellent' };
            if (score >= 70) return { grade: 'B', tier: 'tier_good', insight: 'insight_good' };
            if (score >= 55) return { grade: 'C', tier: 'tier_intermediate', insight: 'insight_beginner' };
            if (score >= 40) return { grade: 'D', tier: 'tier_intermediate', insight: 'insight_beginner' };
            return { grade: 'F', tier: 'tier_beginner', insight: 'insight_beginner' };
        }

        _scoreRound(state) {
            var ds = state.domainState, period = state.currentPeriod, log = this._log(state);
            var attempts = log.done[period] || Math.max(log.tries[period] || 0, ds.currentAttempts || 0) || 1;
            log.done[period] = attempts;
            if (!Array.isArray(ds.items)) ds.items = [];
            ds.items[period - 1] = { a: attempts, m: attempts > 1 ? (log.miss[period] || ds.firstMiss || 'acct') : '' };
            if (!Array.isArray(ds.slips)) ds.slips = [];
            var ls = log.slips[period] || [];
            for (var s = 0; s < ls.length; s++) { if (ds.slips.indexOf(ls[s]) < 0 && ds.slips.length < 60) ds.slips.push(ls[s]); }
            var g = this._grade(ds.items), b = this._band(g.overall);
            var points = attempts === 1 ? 3 : (attempts === 2 ? 2 : (attempts === 3 ? 1 : 0));
            ds.score = g.points;
            ds.totalCorrect = g.n;
            ds.firstTry = g.first;
            ds.totalAttempts = g.attempts;
            ds.conceptsKept = g.kept;
            if (!Array.isArray(ds.scoreHistory)) ds.scoreHistory = [];
            ds.scoreHistory.length = Math.min(ds.scoreHistory.length, period - 1);
            ds.scoreHistory[period - 1] = g.overall;
            ds.currentAttempts = 0;
            ds.firstMiss = '';
            ds.gradeShown = String(g.overall);
            // Grade contract (USF C1): express/results_utils.php reads domainState.performance.overallScore every period.
            ds.performance = { overallScore: g.overall, grade: b.grade, tier: b.tier, insights: [],
                accuracy: g.accuracy, concepts: g.concepts, conceptsKept: g.kept };
            var lang = this._getLang(), taskDesc;
            if (period <= 18) taskDesc = (lang === 'es' ? 'Día ' : 'Day ') + this.EVENTS[period - 1].day;
            else taskDesc = lang === 'es' ? this.ANALYSIS[period - 19].heading_es : this.ANALYSIS[period - 19].heading_en;
            return { period: period, phase: period <= 18 ? 1 : this.ANALYSIS[Math.min(period - 19, 3)].phase, taskDesc: taskDesc,
                attempts: attempts, points: points, cumulativeScore: g.points, correct: g.n, overallScore: g.overall };
        }

        // The briefing for the next task is refreshed on the framework event period:submitted (setupUI).
        calculateResults(state) {
            var r = this._scoreRound(state);
            return { period: r.period, phase: r.phase, taskDesc: r.taskDesc, attempts: r.attempts, points: r.points,
                cumulativeScore: r.cumulativeScore, correct: r.correct, overallScore: r.overallScore, score: r.overallScore };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('scoreDisplay', 'domainState.gradeShown', function(v) { return v ? String(v) : '—'; });
            uiManager.bind('correctDisplay', 'domainState.firstTry', function(v) { return (v || 0) + ' / 22'; });
            uiManager.bind('attemptsDisplay', 'domainState.totalAttempts');
            uiManager.bind('phaseDisplay', 'currentPeriod', function(v) {
                if (v <= 18) return '1';
                if (v === 19) return '2';
                if (v <= 21) return '3';
                return '4';
            });

            var self = this;
            var fw = window.mySimulation;
            // Drive the briefing off framework events instead of a timer (see calculateResults).
            if (fw && fw.eventBus && typeof fw.eventBus.on === 'function') {
                fw.eventBus.on('period:submitted', function() { try { self._updateBriefing(fw.state); } catch (e) {} });
                fw.eventBus.on('period:undone', function() { try { self._updateBriefing(fw.state); } catch (e) {} });
            }
            if (typeof document !== 'undefined' && document.addEventListener) {
                document.addEventListener('express:langchanged', function() {
                    try {
                        if (window.mySimulation) self._updateBriefing(window.mySimulation.state);
                        self._applyAriaLabels();
                        self._relabelChart();
                    } catch (e) {}
                });
            }
            this._applyAriaLabels();
        }

        _applyAriaLabels() {
            var t = this._t();
            try {
                var c = document.getElementById('scoreChart');
                if (c) c.setAttribute('aria-label', t('chart_aria'));
                var sc = document.querySelector('.acctgame-sim-status-cards');
                if (sc) sc.setAttribute('aria-label', t('status_region'));
                var bc = document.getElementById('briefingCard');
                if (bc) bc.setAttribute('aria-label', t('briefing_region'));
            } catch (e) {}
        }

        // Chart text is drawn on the canvas, so a language switch has to set it again.
        _relabelChart() {
            var fw = window.mySimulation, t = this._t();
            var ch = fw && fw.uiManager && fw.uiManager.charts ? fw.uiManager.charts.scoreChart : null;
            if (!ch || !ch.options) return;
            try {
                if (ch.data && ch.data.datasets && ch.data.datasets[0]) ch.data.datasets[0].label = t('chart_series');
                if (ch.options.plugins && ch.options.plugins.title) ch.options.plugins.title.text = t('chart_title');
                if (ch.options.scales && ch.options.scales.x && ch.options.scales.x.title) ch.options.scales.x.title.text = t('chart_x');
                if (ch.options.scales && ch.options.scales.y && ch.options.scales.y.title) ch.options.scales.y.title.text = t('chart_y');
                if (typeof ch.update === 'function') ch.update();
            } catch (e) {}
        }

        getChartConfig() {
            var t = this._t();
            return {
                scoreChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: t('chart_series'),
                            data: [],
                            borderColor: '#1a5276',
                            backgroundColor: 'rgba(26,82,118,0.08)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.2
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: t('chart_title') } },
                        scales: {
                            x: { title: { display: true, text: t('chart_x') } },
                            y: { min: 0, max: 100, title: { display: true, text: t('chart_y') } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var sh = (state && state.domainState && state.domainState.scoreHistory) || [];
            var labels = sh.map(function(_, i) { return String(i + 1); });
            return {
                scoreChart: {
                    labels: labels,
                    datasets: [{ data: sh }]
                }
            };
        }

        // What a run shows, from the last saved round (or the live state), with the history rows as fallback.
        _runFacts(history) {
            var t = this._t();
            // the items come from the last saved round (or the live state); the history rows are the fallback
            var last = history[history.length - 1] || {};
            var ds = last.domainState || (window.mySimulation && window.mySimulation.state && window.mySimulation.state.domainState) || {};
            var items = Array.isArray(ds.items) ? ds.items.slice() : [];
            for (var i = 0; i < history.length; i++) {
                var r = history[i].results || {}, p = r.period || i + 1;
                if (!items[p - 1] && r.attempts) items[p - 1] = { a: r.attempts, m: r.attempts > 1 ? 'acct' : '' };
            }
            var g = this._grade(items), b = this._band(g.overall);
            var pct = g.overall;

            // turning point: the task that took the most attempts (the first such task)
            var tp = null;
            for (var j = 0; j < items.length; j++) {
                if (items[j] && items[j].a > 1 && (!tp || items[j].a > tp.a)) tp = { p: j + 1, a: items[j].a };
            }
            var slips = Array.isArray(ds.slips) ? ds.slips.filter(function (x) { return typeof x === 'string'; }) : [];

            // one row per concept: held, or missed with what this run shows about it
            var concepts = [];
            for (var c = 0; c < this.CONCEPTS.length; c++) {
                var C = this.CONCEPTS[c], lines = [];
                if (!g.held[C.key]) {
                    for (var s = 0; s < slips.length; s++) {
                        var sp = parseInt(slips[s], 10);
                        if (C.items.indexOf(sp) < 0) continue;
                        if (C.accountsOnly && items[sp - 1] && items[sp - 1].m === 'amount') continue;
                        var txt = this._slipText(t, slips[s]);
                        if (txt && lines.indexOf(txt) < 0) lines.push(txt);
                    }
                    if (!lines.length) lines.push(t('cmiss_' + C.key));
                }
                concepts.push({ key: C.key, held: g.held[C.key], label: t('concept_' + C.key), lines: lines });
            }
            return { items: items, g: g, b: b, pct: pct, tp: tp, concepts: concepts };
        }

        getPerformanceSummary(history) {
            var t = this._t();
            if (!history || !history.length) {
                return { totalPeriods: 0, message: t('insight_beginner'), insights: [] };
            }
            var F = this._runFacts(history), g = F.g, b = F.b, pct = F.pct, tp = F.tp;

            var insights = [];
            insights.push(this._fill(t('insight_accuracy'), { a: g.first, pct: Math.round(g.first / 22 * 100), j: g.firstJ, s: g.firstA, h: g.hints }));
            insights.push(this._fill(t('insight_concepts'), { k: g.kept }));
            if (tp) {
                var tpTask = tp.p <= 18 ? this._fill(t('task_event'), { n: tp.p, day: this.EVENTS[tp.p - 1].day }) : t('task_a' + (tp.p - 18));
                var tpPts = tp.a === 2 ? 2 : (tp.a === 3 ? 1 : 0);
                insights.push(this._fill(t('insight_turning'), { task: tpTask, k: tp.a, pts: tpPts }));
            } else {
                insights.push(t('insight_clean'));
            }

            var L = this._ledgerFigures();
            var pctFmt = function (x) { return (Math.round(x * 10000) / 100).toFixed(2) + '%'; };
            return {
                totalPeriods: history.length,
                totalPoints: g.points,
                maxPoints: 66,
                percentage: pct,
                overallScore: pct,
                totalScore: pct,
                score: pct,
                composite: pct,
                accuracyScore: g.accuracy,
                conceptScore: g.concepts,
                conceptsKept: g.kept,
                totalCorrect: history.length,
                firstTryCorrect: g.first,
                hintsNeeded: g.hints,
                totalAttempts: g.attempts,
                performance: b.tier,
                performanceKey: b.tier,
                performanceLabel: t(b.tier),
                tier: b.tier,
                grade: b.grade,
                message: t(b.insight),
                insights: insights,
                questions: [ this._fill(t('q_tb'), { tb: this._money(L.tb) }),
                             this._fill(t('q_close'), { ta: this._money(L.ta), liab: this._money(L.liab), cs: this._money(L.equityClosed - L.ni), ni: this._money(L.ni) }),
                             t('q_loan') ],
                grossProfitMargin: pctFmt(L.gross / L.netSales),
                netProfitMargin: pctFmt(L.ni / L.netSales),
                currentRatio: L.cr.toFixed(2),
                debtToEquity: (Math.round(L.liab / L.equityClosed * 100) / 100).toFixed(2)
            };
        }

        formatCompletionMessage(summary) {
            var t = this._t();
            summary = summary || {};
            var pct = Math.round(summary.percentage != null ? summary.percentage : (summary.overallScore || 0));
            var b = this._band(pct);
            var insights = summary.insights && summary.insights.length ? summary.insights : [ t(b.insight) ];
            var questions = summary.questions || [];
            var concepts = [];
            try {
                var st = window.mySimulation && window.mySimulation.state;
                if (st && st.history && st.history.length) concepts = this._runFacts(st.history).concepts;
            } catch (e) { concepts = []; }

            var lis = '';
            for (var i = 0; i < insights.length; i++) { lis += '<li>' + insights[i] + '</li>'; }
            var qs = '';
            for (var q = 0; q < questions.length; q++) { qs += '<li>' + questions[q] + '</li>'; }
            var crows = '';
            for (var c = 0; c < concepts.length; c++) {
                var C = concepts[c];
                crows += '<li class="acctgame-concept ' + (C.held ? 'acctgame-concept-held' : 'acctgame-concept-missed') + '">' +
                    '<span class="acctgame-concept-name">' + C.label + '</span> ' +
                    '<span class="acctgame-concept-status">' + t(C.held ? 'concept_held' : 'concept_missed') + '</span>' +
                    (C.lines && C.lines.length ? '<span class="acctgame-concept-why">' + C.lines.join('<br>') + '</span>' : '') + '</li>';
            }

            function kpi(labelKey, value) {
                return '<div class="acctgame-sim-completion-ratio">' +
                    '<span class="acctgame-ratio-label">' + t(labelKey) + '</span>' +
                    '<span class="acctgame-ratio-value">' + value + '</span></div>';
            }
            var first = summary.firstTryCorrect != null ? summary.firstTryCorrect : 0;
            var parts = kpi('kpi_concepts', (summary.conceptScore != null ? summary.conceptScore : 0) + ' / 60') +
                kpi('kpi_accuracy', (summary.accuracyScore != null ? String(summary.accuracyScore) : '0') + ' / 40');
            var process = kpi('kpi_first_try', first + ' / 22') + kpi('kpi_attempts', String(summary.totalAttempts || 0)) +
                kpi('kpi_hints', String(summary.hintsNeeded || 0)) + kpi('kpi_points', (summary.totalPoints || 0) + ' / 66');
            var ratios =
                kpi('ratio_gross_margin', summary.grossProfitMargin || '') +
                kpi('ratio_net_margin', summary.netProfitMargin || '') +
                kpi('ratio_current', summary.currentRatio || '') +
                kpi('ratio_debt_equity', summary.debtToEquity || '');

            return '' +
                '<div class="acctgame-sim-completion">' +
                    '<h3>' + t('completion_heading') + '</h3>' +
                    '<div class="acctgame-sim-completion-grade" role="img" aria-label="' + t('completion_grade_aria') + ' ' + b.grade + '">' + b.grade + '</div>' +
                    '<p class="acctgame-sim-completion-score">' + t('completion_score_label') + ': <strong>' + pct + '/100</strong></p>' +
                    '<p class="acctgame-sim-completion-tier">' + t(b.tier) + '</p>' +
                    '<div class="acctgame-sim-completion-ratios">' + parts + '</div>' +
                    '<p class="acctgame-sim-completion-note">' + t('grade_rule') + '</p>' +
                    (crows ? '<p class="acctgame-sim-completion-ratios-heading"><strong>' + t('concepts_heading') + '</strong></p><ul class="acctgame-concepts">' + crows + '</ul>' : '') +
                    '<p class="acctgame-sim-completion-ratios-heading"><strong>' + t('process_heading') + '</strong></p>' +
                    '<div class="acctgame-sim-completion-ratios">' + process + '</div>' +
                    (lis ? '<p class="acctgame-sim-completion-ratios-heading"><strong>' + t('insights_heading') + '</strong></p><ul class="acctgame-sim-completion-insights">' + lis + '</ul>' : '') +
                    '<p class="acctgame-sim-completion-ratios-heading"><strong>' + t('ratios_heading') + '</strong></p>' +
                    '<div class="acctgame-sim-completion-ratios">' + ratios + '</div>' +
                    (qs ? '<p class="acctgame-sim-completion-ratios-heading"><strong>' + t('questions_heading') + '</strong></p><ol class="acctgame-sim-completion-insights">' + qs + '</ol>' : '') +
                '</div>';
        }

        getHint(state, results) {
            var t = this._t();
            var period = state && state.currentPeriod;
            if (!period) return null;
            if (period <= 18) return t('hint_rule');
            if (period <= 21) return t('hint_ledger');
            return null;
        }

